 129→/// Owner writes chat message (list layer), node receives via SyncOffer
 130→///
 131→/// **Bug coverage**: Pattern-based layer names ({page_id}/messages) require
 132→/// gurkha pattern expansion in can_write_layer(). Catches mismatches between
 133→/// actual layer names and permit patterns.
 134→#[tokio::test]
 135→async fn test_owner_chat_layer_sync_to_node() -> Result<()> {
 136→    init_tracing();
 137→
 138→    let mut s = Scenario::builder()
 139→        .app("osvauld-demos")
 140→        .published()
 141→        .build()
 142→        .await?;
 143→
 144→    let page_id = s.space().page_id.clone();
 145→    let messages_layer = "messages".to_string();
 146→
 147→    sleep(Duration::from_millis(500)).await;
 148→
 149→    // Owner opens page and writes a chat message
 150→    let owner_scribe = s.owner().butler.open_page(&page_id).await?;
 151→
 152→    let (reply_tx, reply_rx) = tokio::sync::oneshot::channel();
 153→    owner_scribe.cast(ScribeMessage::EnsureLoroList {
 154→        layer_name: messages_layer.clone(),
 155→        reply: reply_tx,
 156→    }).map_err(|e| anyhow::anyhow!("Failed to ensure list: {:?}", e))?;
 157→    reply_rx.await??;
 158→
 159→    owner_scribe.cast(ScribeMessage::ListPush {
 160→        layer_name: messages_layer.clone(),
 161→        path: String::new(),
 162→        item: serde_json::json!({
 163→            "text": "Hello from owner",
 164→            "sender": "owner",
 165→            "timestamp": 1234567890
 166→        }),
 167→    }).map_err(|e| anyhow::anyhow!("Failed to push message: {:?}", e))?;
 168→
 169→    // Wait for message to arrive on node
 170→    let node_data = wait_for_layer_data(
 171→        &s.node().butler,
 172→        &page_id,
 173→        &messages_layer,
 174→        Duration::from_secs(10),
 175→    ).await?;
 176→
 177→    assert!(!node_data.is_empty(), "Node should have received chat layer data");
 178→
 179→    s.shutdown().await;
 180→    Ok(())
 181→}
