 245→/// Viewer add_website bootstrap creates and syncs protocol sync-meta layer to node.
 246→#[tokio::test]
 247→async fn diagnostic_viewer_add_website_bootstrap_sync_meta_to_node() -> Result<()> {
 248→    init_tracing();
 249→
 250→    let mut s = Scenario::builder()
 251→        .app("osvauld-demos")
 252→        .published()
 253→        .viewers(1)
 254→        .build()
 255→        .await?;
 256→
 257→    let page_id = s.space().page_id.clone();
 258→    let space_id = s.space().space_id.clone();
 259→
 260→    let viewer_link = s.get_viewer_link(&space_id).await?;
 261→    s.add_viewer(0, &viewer_link, &page_id).await?;
 262→
 263→    let viewer_did = s.viewer(0).butler.user_info().await?.did;
 264→    let owner_did = s.owner().butler.user_info().await?.did;
 265→    let viewer_sync_meta_layer = format!("__sync_meta/{}", viewer_did);
 266→    let owner_sync_meta_layer = format!("__sync_meta/{}", owner_did);
 267→
 268→    // Wait for viewer bootstrap sync-meta to reach node.
 269→    wait_until("node has viewer sync-meta layer", Duration::from_secs(10), || {
 270→        s.node()
 271→            .butler
 272→            .store()
 273→            .get_layer(&page_id, &viewer_sync_meta_layer)
 274→            .ok()
 275→            .flatten()
 276→    })
 277→    .await?;
 278→
 279→    // Viewer should not receive owner's sync-meta layer.
 280→    let viewer_has_owner_sync_meta = s
 281→        .viewer(0)
 282→        .butler
 283→        .store()
 284→        .get_layer(&page_id, &owner_sync_meta_layer)?
 285→        .is_some();
 286→    assert!(
 287→        !viewer_has_owner_sync_meta,
 288→        "viewer must not receive owner's __sync_meta layer"
 289→    );
 290→
 291→    let viewer_page = s
 292→        .viewer(0)
 293→        .butler
 294→        .pages()
 295→        .get(&page_id)?
 296→        .expect("viewer should have page");
 297→    let viewer_permit = viewer_page
 298→        .permit
 299→        .clone()
 300→        .expect("viewer page should have permit");
 301→    let parsed_viewer_permit = gurkha::Permit::from_token(&viewer_permit)?;
 302→    let expected_sync_layers = expected_sync_layers_from_permit(&parsed_viewer_permit, &page_id);
 303→
 304→    let viewer_sync_meta_json = get_layer_json(s.viewer(0), &page_id, &viewer_sync_meta_layer).await?;
 305→    assert_sync_meta_entries(&viewer_sync_meta_json, &expected_sync_layers);
 306→
 307→    let node_sync_meta_json = get_layer_json(s.node(), &page_id, &viewer_sync_meta_layer).await?;
 308→    assert_sync_meta_entries(&node_sync_meta_json, &expected_sync_layers);
 309→
 310→    s.shutdown().await;
 311→    Ok(())
 312→}
