 538→/// Dynamic layer syncs from owner → node → viewer (full chain)
 539→///
 540→/// **Bug coverage**: Node receives dynamic layer from owner but doesn't forward to viewers
 541→/// because SubscriberInfo.layer_permits is empty. The fix: emit_dynamic_layer_permits
 542→/// adds permits to node's SubscriberInfo before emitting SyncEvent::NewDynamicLayer.
 543→#[tokio::test]
 544→async fn test_dynamic_layer_syncs_to_viewer() -> Result<()> {
 545→    init_tracing();
 546→
 547→    let mut s = Scenario::builder()
 548→        .app("osvauld-demos")
 549→        .published()
 550→        .viewers(1)
 551→        .build()
 552→        .await?;
 553→
 554→    let page_id = s.space().page_id.clone();
 555→    let space_id = s.space().space_id.clone();
 556→
 557→    sleep(Duration::from_millis(500)).await;
 558→
 559→    // Connect viewer first
 560→    let viewer_link = s.get_viewer_link(&space_id).await?;
 561→    s.add_viewer(0, &viewer_link, &page_id).await?;
 562→
 563→    sleep(Duration::from_millis(500)).await;
 564→
 565→    // Owner creates dynamic layer and writes data
 566→    let owner_scribe = s.owner().butler.open_page(&page_id).await?;
 567→
 568→    let (reply_tx, reply_rx) = tokio::sync::oneshot::channel();
 569→    owner_scribe.cast(ScribeMessage::CreateDynamicLayer {
 570→        schema_key: "channels/{id}/messages".to_string(),
 571→        layer_id: "general".to_string(),
 572→        reply: reply_tx,
 573→    }).map_err(|e| anyhow::anyhow!("Failed to create dynamic layer: {:?}", e))?;
 574→
 575→    let full_layer_name = reply_rx.await
 576→        .map_err(|_| anyhow::anyhow!("CreateDynamicLayer channel closed"))?
 577→        .map_err(|e| anyhow::anyhow!("CreateDynamicLayer failed: {}", e))?;
 578→
