  1→//! Typed CRDT operation handlers
  2→//!
  3→//! Handles list, map, and counter operations for Scribe actor.
  4→//! **Broadcast**: Handled automatically by Loro observer after commit()
  5→//!
  6→//! **Path convention**:
  7→//! - Empty path ("") = use layer_name as container name directly (Lua bindings)
  8→//! - Non-empty path = use root map pattern with nested containers (template actions)
  9→
 10→use tracing::{debug, info, instrument};
 11→
 12→use crate::{ScribeError, Result};
 13→use domains::json_to_loro_value;
 14→
 15→use crate::layer_unit::LayerUnit;
 16→use crate::state::ScribeState;
 17→use crate::loro_observer;
 18→
 19→// Typed CRDT Operation Handlers
 20→
 21→/// Helper to ensure a layer exists, returns true if layer was newly created
 22→fn ensure_layer_exists(state: &mut ScribeState, layer_name: &str) -> bool {
 23→    let is_new = !state.units.contains_key(layer_name);
 24→    if is_new {
 25→        let mut unit = LayerUnit::new_empty();
 26→        unit.set_local_only(!state.should_sync_layer(layer_name));
 27→        state.units.insert(layer_name.to_string(), unit);
 28→        state.track_new_sync_layer_in_meta(layer_name);
 29→        debug!(layer = %layer_name, "Created new layer");
 30→    }
 31→    is_new
 32→}
 33→
 34→/// Handle list push operation (append)
 35→///
 36→/// **Broadcast**: Loro observer triggers broadcast after commit()
 37→/// **Path**: Empty = use layer_name as container; non-empty = root map pattern
 38→#[instrument(skip(state, item), fields(page_id = %state.page_id, layer = %layer_name, path = %path))]
 39→pub async fn handle_list_push(
 40→    state: &mut ScribeState,
 41→    layer_name: &str,
 42→    path: &str,
 43→    item: serde_json::Value,
 44→) -> Result<()> {
 45→    info!("ListPush operation");
 46→
 47→    // Ensure layer exists
 48→    let is_new_layer = ensure_layer_exists(state, layer_name);
 49→
 50→    let unit = state.units.get_mut(layer_name)
 51→        .ok_or_else(|| ScribeError::LayerNotFound(layer_name.to_string()))?;
 52→
 53→    if path.is_empty() {
 54→        // Lua pattern: use layer_name as container name directly
 55→        let list = unit.layer().loro().get_list(layer_name);
 56→        let loro_value = json_to_loro_value(&item);
 57→        list.push(loro_value)
 58→            .map_err(|e| ScribeError::CrdtError(format!("ListPush: {}", e)))?;
 59→        unit.layer().commit();
 60→    } else {
 61→        // Template pattern: use root map with nested path
 62→        unit.layer().list_push(path, &item)
 63→            .map_err(|e| ScribeError::CrdtError(format!("Layer: {}", e)))?;
 64→    }
 65→
 66→    unit.mark_dirty();
 67→
 68→    // Set up observer if new layer (after first write)
 69→    if is_new_layer {
 70→        loro_observer::setup_layer_observer(state, layer_name);
 71→    }
 72→
 73→    Ok(())
 74→}
 75→
 76→/// Handle list insert operation
 77→///
 78→/// **Broadcast**: Loro observer triggers broadcast after commit()
 79→/// **Path**: Empty = use layer_name as container; non-empty = root map pattern
 80→#[instrument(skip(state, item), fields(page_id = %state.page_id, layer = %layer_name, path = %path))]
 81→pub async fn handle_list_insert(
 82→    state: &mut ScribeState,
 83→    layer_name: &str,
 84→    path: &str,
 85→    index: usize,
 86→    item: serde_json::Value,
 87→) -> Result<()> {
 88→    info!("ListInsert operation");
 89→
 90→    let is_new_layer = ensure_layer_exists(state, layer_name);
 91→
 92→    let unit = state.units.get_mut(layer_name)
 93→        .ok_or_else(|| ScribeError::LayerNotFound(layer_name.to_string()))?;
 94→
 95→    if path.is_empty() {
 96→        // Lua pattern: use layer_name as container name directly
 97→        let list = unit.layer().loro().get_list(layer_name);
 98→        let loro_value = json_to_loro_value(&item);
 99→        list.insert(index, loro_value)
100→            .map_err(|e| ScribeError::CrdtError(format!("ListInsert: {}", e)))?;
101→        unit.layer().commit();
102→    } else {
103→        // Template pattern: use root map with nested path
104→        unit.layer().list_insert(path, index, &item)
105→            .map_err(|e| ScribeError::CrdtError(format!("Layer: {}", e)))?;
106→    }
107→
108→    unit.mark_dirty();
109→
110→    if is_new_layer {
111→        loro_observer::setup_layer_observer(state, layer_name);
112→    }
113→
114→    Ok(())
115→}
116→
117→/// Handle list delete operation
118→///
119→/// **Broadcast**: Loro observer triggers broadcast after commit()
120→/// **Path**: Empty = use layer_name as container; non-empty = root map pattern
121→#[instrument(skip(state), fields(page_id = %state.page_id, layer = %layer_name, path = %path))]
122→pub async fn handle_list_delete(
123→    state: &mut ScribeState,
124→    layer_name: &str,
125→    path: &str,
126→    index: usize,
127→) -> Result<()> {
128→    info!("ListDelete operation");
129→
130→    let is_new_layer = ensure_layer_exists(state, layer_name);
131→
132→    let unit = state.units.get_mut(layer_name)
133→        .ok_or_else(|| ScribeError::LayerNotFound(layer_name.to_string()))?;
134→
135→    if path.is_empty() {
136→        // Lua pattern: use layer_name as container name directly
137→        let list = unit.layer().loro().get_list(layer_name);
138→        list.delete(index, 1)
139→            .map_err(|e| ScribeError::CrdtError(format!("ListDelete: {}", e)))?;
140→        unit.layer().commit();
141→    } else {
142→        // Template pattern: use root map with nested path
143→        unit.layer().list_delete(path, index)
144→            .map_err(|e| ScribeError::CrdtError(format!("Layer: {}", e)))?;
145→    }
146→
147→    unit.mark_dirty();
148→
149→    if is_new_layer {
150→        loro_observer::setup_layer_observer(state, layer_name);
151→    }
152→
153→    Ok(())
154→}
155→
156→/// Handle map insert operation
157→///
158→/// **Broadcast**: Loro observer triggers broadcast after commit()
159→/// **Path**: Empty = use layer_name as container; non-empty = root map pattern
160→#[instrument(skip(state, value), fields(page_id = %state.page_id, layer = %layer_name, path = %path))]
161→pub async fn handle_map_insert(
162→    state: &mut ScribeState,
163→    layer_name: &str,
164→    path: &str,
165→    key: &str,
166→    value: serde_json::Value,
167→) -> Result<()> {
168→    info!("MapInsert operation");
169→
170→    let is_new_layer = ensure_layer_exists(state, layer_name);
171→
172→    let unit = state.units.get_mut(layer_name)
173→        .ok_or_else(|| ScribeError::LayerNotFound(layer_name.to_string()))?;
174→
175→    if path.is_empty() {
176→        // Lua pattern: use layer_name as container name directly
177→        let map = unit.layer().loro().get_map(layer_name);
178→        let loro_value = json_to_loro_value(&value);
179→        map.insert(key, loro_value)
180→            .map_err(|e| ScribeError::CrdtError(format!("MapInsert: {}", e)))?;
181→        unit.layer().commit();
182→    } else {
183→        // Template pattern: use root map with nested path
184→        unit.layer().map_insert(path, key, &value)
185→            .map_err(|e| ScribeError::CrdtError(format!("Layer: {}", e)))?;
186→    }
187→
188→    unit.mark_dirty();
189→
