 29→// Update Context - Centralized Decision Logic
 30→
 31→/// Context for an incoming update - computed once, used throughout
 32→///
 33→/// **Design**: All decisions about how to handle an update are computed upfront.
 34→/// This makes the apply flow clearer and easier to test.
 35→#[derive(Debug)]
 36→pub struct UpdateContext {
 37→    /// Layer being updated
 38→    pub layer_name: String,
 39→    /// Source of update: None = local, Some = remote peer (user_did, device_id)
 40→    pub from_peer: Option<(String, String)>,
 41→    /// Role of the peer (for validation) - "node", "owner", "viewer", etc.
 42→    pub peer_role: String,
 43→
 44→    /// Is this a remote update (from a peer)?
 45→    pub is_remote: bool,
 46→    /// Is this layer local-only (never synced)?
 47→    pub is_local_only: bool,
 48→    /// Does this update need Lua validation?
 49→    pub should_validate: bool,
 50→    /// Should we broadcast after applying?
 51→    pub should_broadcast: bool,
 52→    /// Is this a new layer (needs creation)?
 53→    pub is_new_layer: bool,
 54→}
 55→
 56→impl UpdateContext {
 57→    /// Create context for an incoming update
 58→    ///
 59→    /// **Context**: Computes all decisions based on state and update metadata
 60→    /// **Note**: Permission checks are done separately (may reject before context is useful)
 61→    pub fn new(
 62→        state: &ScribeState,
 63→        layer_name: &str,
 64→        from_peer: Option<(String, String)>,
 65→    ) -> Self {
 66→        let is_remote = from_peer.is_some();
 67→        let is_local_only = Permissions::is_local_only(layer_name);
 68→        let is_new_layer = !state.units.contains_key(layer_name);
 69→
 70→        // Determine peer role for validation
 71→        let peer_role = if let Some(ref peer) = from_peer {
 72→            get_peer_role(state, &peer.0)
 73→        } else {
 74→            "local".to_string()
 75→        };
 76→
 77→        // Should validate: remote update AND ValidationHandle exists
 78→        let should_validate = is_remote && state.validation_handle.is_some();
 79→
 80→        // Should broadcast: remote update (local updates use observer)
 81→        let should_broadcast = is_remote;
 82→
 83→        Self {
 84→            layer_name: layer_name.to_string(),
 85→            from_peer,
 86→            peer_role,
 87→            is_remote,
 88→            is_local_only,
 89→            should_validate,
 90→            should_broadcast,
 91→            is_new_layer,
 92→        }
 93→    }
 94→}
 95→
 96→// Apply Outcome - Event-Driven Pattern
 97→
 98→/// Outcome of applying an update
 99→///
100→/// **Design**: Separates the "what happened" from "what to do next"
101→/// This enables cleaner outcome handling and better error messages
102→#[derive(Debug)]
103→pub enum ApplyOutcome {
104→    /// Update was successfully applied
105→    Applied {
106→        /// Layer that was updated
107→        layer_name: String,
108→        /// Ops extracted from update (for derivation)
109→        ops: Vec<JsonOp>,
110→        /// Was a new layer created?
111→        created_layer: bool,
112→    },
113→    /// Update was rejected
114→    Rejected {
115→        /// Reason for rejection
116→        reason: String,
117→    },
118→}
119→
120→// Apply Update Handler
121→
122→/// Handle layer update (local or remote)
123→///
124→/// **Context**: Edit from UI or sync push from peer
125→/// **We do**: Permission check, validation, CRDT merge
126→/// **Broadcast**: Handled automatically by Loro observer (set up at startup)
127→/// **Returns**: Ok(()) on success, Err(message) on failure
128→#[instrument(skip(state, update, permit), fields(page_id = %state.page_id, layer = %ShortLayer(layer_name)))]
129→pub async fn handle_apply_update(
130→    state: &mut ScribeState,
131→    layer_name: &str,
132→    update: &[u8],
133→    from_peer: Option<(String, String)>,
134→    permit: Option<&str>,
135→) -> std::result::Result<(), String> {
136→    let _ = permit; // Permit is used for subscription in Courier, not here
137→
138→    // Defense-in-depth: normalize layer name (strip page_id/ prefix)
139→    let layer_name = normalize_layer_name(layer_name, &state.page_id);
140→    let layer_name = layer_name.as_str();
141→
142→    // Build context - computes all decisions upfront
143→    let ctx = UpdateContext::new(state, layer_name, from_peer.clone());
144→
145→    // Step 1: Apply the update (with permission checks, validation, CRDT merge)
146→    let outcome = apply_update_core(state, &ctx, update).await;
147→
148→    // Step 2: Handle the outcome
149→    let from_peer_did = ctx.from_peer.as_ref().map(|(d, _)| d.as_str());
150→    match outcome {
151→        ApplyOutcome::Applied { layer_name, ops: _, created_layer } => {
152→            // Mark layer as dirty for persistence
153→            if let Some(unit) = state.units.get_mut(&layer_name) {
154→                unit.mark_dirty();
155→            }
156→            debug!(layer = %layer_name, created = created_layer, "Update applied successfully");
157→            state.emit_apply_update_capture(&layer_name, from_peer_did, "applied", None);
158→
159→            // Post-apply handling for remote updates
160→            if ctx.is_remote {
161→                handle_post_apply(state, &layer_name, ctx.from_peer.clone()).await;
162→            }
163→
164→            // Node-side: detect new dynamic layers and issue permits
165→            if created_layer {
166→                if let Some(ref from_peer) = ctx.from_peer {
167→                    emit_dynamic_layer_permits(state, &layer_name, from_peer).await;
168→                }
169→            }
170→
171→            // Update sender's vector
172→            if let Some(ref peer) = ctx.from_peer {
173→                update_sender_vector(state, peer, &layer_name);
174→            }
175→
176→            // Broadcast to eligible subscribers
177→            if ctx.should_broadcast {
178→                broadcast_update(state, &layer_name, ctx.from_peer.as_ref()).await;
179→            }
180→
181→            // Note: Derivation is now handled externally by kunki/LuaRuntime
182→            // which subscribes to PageUpdate::LayerChanged events
183→
184→            Ok(())
185→        }
186→        ApplyOutcome::Rejected { reason } => {
187→            warn!(layer = %layer_name, reason = %reason, "Update rejected");
188→            state.emit_apply_update_capture(layer_name, from_peer_did, "rejected", Some(&reason));
189→            Err(reason)
190→        }
191→    }
192→}
193→
194→/// Core apply logic - returns ApplyOutcome
195→///
196→/// **Context**: Separated from handle_apply_update for cleaner testing
197→/// **Returns**: ApplyOutcome::Applied or ApplyOutcome::Rejected
198→#[instrument(skip_all, fields(page_id = %state.page_id, layer = %ctx.layer_name))]
199→async fn apply_update_core(
200→    state: &mut ScribeState,
201→    ctx: &UpdateContext,
202→    update: &[u8],
203→) -> ApplyOutcome {
204→    // Step 1: Permission check - reject local_only layers from remote
205→    if ctx.is_remote && ctx.is_local_only {
206→        return ApplyOutcome::Rejected {
207→            reason: "local_only layer cannot be updated by remote peer".to_string(),
208→        };
209→    }
210→
211→    // Step 2: Permission check for remote updates
212→    if let Some(ref peer) = ctx.from_peer {
213→        if !Permissions::can_write(state, peer, &ctx.layer_name) {
214→            return ApplyOutcome::Rejected {
215→                reason: "Permission denied: cannot write to layer".to_string(),
216→            };
217→        }
218→    }
219→
220→    // Step 3: Extract ops for validation (using optimized pre-commit method)
221→    let extracted_ops = if ctx.should_validate {
222→        // Use Layer::extract_ops_from_bytes (5-10x faster than old fork+diff)
223→        match Layer::extract_ops_from_bytes(update) {
224→            Ok(ops) => Some(ops),
225→            Err(e) => {
226→                // Log extraction failure - validation will proceed with empty ops
227→                // This could mask invalid updates, so log at warn level
228→                warn!(layer = %ctx.layer_name, error = %e, "Failed to extract ops from update, proceeding with empty ops");
229→                None
230→            }
231→        }
232→    } else {
233→        None
234→    };
235→
236→    // Step 4: Validate with Lua (if needed)
237→    if ctx.should_validate {
238→        if let Err(e) = validate_update_with_context(state, ctx, &extracted_ops).await {
239→            return ApplyOutcome::Rejected { reason: e };
240→        }
241→    }
242→
243→    // Step 5: Create layer if needed (remote only)
244→    let created_layer = if ctx.is_new_layer {
245→        if ctx.is_remote {
246→            create_layer_from_peer(state, &ctx.layer_name);
247→            true
248→        } else {
249→            return ApplyOutcome::Rejected {
250→                reason: "Layer not found".to_string(),
251→            };
252→        }
253→    } else {
254→        false
255→    };
256→
257→    // Step 6: Apply CRDT update
258→    if let Err(e) = apply_crdt_update(state, &ctx.layer_name, update, ctx.from_peer.clone()) {
259→        return ApplyOutcome::Rejected { reason: e };
260→    }
261→
262→    ApplyOutcome::Applied {
263→        layer_name: ctx.layer_name.clone(),
264→        ops: extracted_ops.unwrap_or_default(),
265→        created_layer,
266→    }
267→}
