456→/// Detect if a newly created layer matches a dynamic schema and emit permits
457→///
458→/// **Context**: Node receives a new layer from peer. If it matches a dynamic schema,
459→/// prepare layer permits for all connected peers and emit SyncEvent::NewDynamicLayer.
460→/// **Coordinator** distributes the permits to PeerActors → peers.
461→#[instrument(skip(state), fields(page_id = %state.page_id, layer = %layer_name))]
462→async fn emit_dynamic_layer_permits(
463→    state: &ScribeState,
464→    layer_name: &str,
465→    from_peer: &(String, String),
466→) {
467→    // Only nodes issue permits (require permit_issuer + our_permit + sync_event_tx)
468→    let Some(ref permit_issuer) = state.permit_issuer else { return; };
469→    let Some(ref our_permit) = state.our_permit else { return; };
470→    let Some(ref sync_event_tx) = state.sync_event_tx else { return; };
471→
472→    // Check if layer matches a dynamic schema
473→    let Some((schema_key, schema, creator_did)) =
474→        find_matching_dynamic_schema(our_permit, layer_name, &state.page_id) else { return; };
475→
476→    // Validate creator namespace: sender's DID must match DID in path
477→    if from_peer.0 != creator_did {
478→        warn!(
479→            layer = %layer_name,
480→            sender = %from_peer.0,
481→            creator = %creator_did,
482→            "Creator namespace mismatch — sender DID doesn't match path DID"
483→        );
484→        return;
485→    }
486→
487→    // Mark the layer as dynamic
488→    if let Some(unit) = state.units.get(layer_name) {
489→        // Note: is_dynamic is pub so we'd need get_mut, but we can't mutate here.
490→        // The flag is informational; permit issuance is the critical path.
491→        let _ = unit;
492→    }
493→
494→    // Collect connected peers with their roles
495→    let connected_peers = collect_connected_peers_with_roles(state);
496→
497→    // Prepare layer permits
498→    let full_layer_name = format!("{}/{}", state.page_id, layer_name);
499→    match prepare_layer_permits(
500→        permit_issuer.as_ref(),
501→        &state.page_id,
502→        &full_layer_name,
503→        schema,
504→        &creator_did,
505→        &connected_peers,
506→    ) {
507→        Ok(permits) if !permits.is_empty() => {
508→            info!(
509→                layer = %layer_name,
510→                schema = %schema_key,
511→                creator = %creator_did,
512→                permit_count = permits.len(),
513→                "Prepared dynamic layer permits, emitting NewDynamicLayer"
514→            );
515→
516→            // Authorize recipient DIDs on the LayerUnit for broadcast
517→            if let Some(unit) = state.units.get(layer_name) {
518→                for (recipient_did, _token) in &permits {
519→                    unit.authorize_did(recipient_did);
520→                    state.emit_layer_auth_capture(layer_name, recipient_did, "authorized_dynamic_permit");
521→                    debug!(
522→                        recipient = %recipient_did,
523→                        layer = %layer_name,
524→                        "Authorized subscriber for dynamic layer"
525→                    );
526→                }
527→            }
528→
529→            let event = SyncEvent::NewDynamicLayer {
530→                page_id: state.page_id.clone(),
531→                layer_name: full_layer_name,
532→                permits,
533→            };
534→
535→            state.emit_sync_event_capture(&event);
536→            if let Err(e) = sync_event_tx.send(event).await {
537→                error!(error = %e, "Failed to emit NewDynamicLayer event");
538→            }
539→        }
540→        Ok(_) => {
541→            debug!(layer = %layer_name, "No permits needed for dynamic layer");
542→        }
543→        Err(e) => {
544→            error!(layer = %layer_name, error = %e, "Failed to prepare dynamic layer permits");
545→        }
546→    }
547→}
548→
549→/// Collect connected peers with their roles from subscriber info
550→///
551→/// **Context**: Node needs (did, role) pairs for prepare_layer_permits
552→fn collect_connected_peers_with_roles(state: &ScribeState) -> Vec<(String, String)> {
553→    let mut peers = Vec::new();
554→
555→    if let Ok(subs) = state.subscribers.read() {
556→        for ((did, _device_id), info) in subs.iter() {
557→            let role = info.permit.relationship().unwrap_or("peer").to_string();
558→            // Avoid duplicates (same DID, different devices)
559→            if !peers.iter().any(|(d, _): &(String, String)| d == did) {
560→                peers.push((did.clone(), role));
561→            }
562→        }
563→    }
564→
565→    peers
566→}
567→
568→/// Get role for a peer from their stored permit
569→///
570→/// **Context**: Determining role for Lua validation
571→/// **Checks**:
572→/// 1. Sync target (owner/viewer mode) -> our role's counterpart
573→/// 2. Stored permit (node mode) -> extract role from permit
574→/// 3. Default -> "peer"
575→#[instrument(skip(state), fields(page_id = %state.page_id))]
576→fn get_peer_role(state: &ScribeState, peer_did: &str) -> String {
577→    // If peer is our sync target, they are the "node" from our perspective
578→    if let Some(ref config) = state.sync_config {
579→        if let Some(ref sync_target) = config.sync_target {
580→            if sync_target == peer_did {
581→                return "node".to_string();
582→            }
583→        }
584→    }
585→
586→    // Node mode: look up peer's stored permit and extract role via PermitContext
587→    if let Some(ref resolver) = state.peer_resolver {
588→        if let Some(permit_token) = resolver.load_user_permit(peer_did) {
589→            let role = PermitContext::from_token(&permit_token, &state.page_id, peer_did)
590→                .map(|ctx| ctx.permit().relationship().unwrap_or("peer").to_string())
591→                .unwrap_or_else(|_| "peer".to_string());
592→            debug!(peer_did = %peer_did, role = %role, "Got peer role from stored permit via PermitContext");
593→            return role;
594→        }
595→    }
596→
597→    // Default role
598→    "peer".to_string()
599→}
