140→/// Courier mode (User or Node)
141→#[derive(Debug, Clone, Copy, PartialEq, Eq)]
142→pub enum CourierMode {
143→    /// Running as user's device (connects TO node)
144→    User,
145→    /// Running as always-on node (accepts connections)
146→    Node,
147→}
148→
149→/// Coordinator manages all PeerActors
150→///
151→/// Generic over `C: Connection` to support different transport implementations.
152→pub struct Coordinator<C: Connection> {
153→    _phantom: PhantomData<C>,
154→}
155→
156→impl<C: Connection> Coordinator<C> {
157→    pub fn new() -> Self {
158→        Self { _phantom: PhantomData }
159→    }
160→
161→    /// Emit an event to the app layer via event_tx channel
162→    fn emit_event(state: &CoordinatorState<C>, event: CourierEvent) {
163→        // Serialize to capture broadcast if active
164→        if let Some(tx) = &state.capture_tx {
165→            if let Ok(json) = serde_json::to_string(&serde_json::json!({
166→                "type": "courier_event",
167→                "ts": chrono::Utc::now().format("%Y-%m-%dT%H:%M:%S%.3fZ").to_string(),
168→                "data": &event,
169→            })) {
170→                let _ = tx.send(json);
171→            }
172→        }
173→
174→        if let Some(tx) = &state.event_tx {
175→            if let Err(e) = tx.try_send(event) {
176→                warn!("Failed to emit event: {}", e);
177→            }
178→        }
179→    }
180→
181→    /// Process a ConnectionEvent and convert to CoordinatorMessage
182→    ///
183→    /// **Note**: Transport now only emits lifecycle events (Connected/Disconnected).
184→    /// Message reading is done by PeerSession directly from the Connection.
185→    pub fn from_connection_event(event: transport::ConnectionEvent<C>) -> Option<CoordinatorMessage<C>> {
186→        match event {
187→            transport::ConnectionEvent::Connected { node_id, conn } => {
188→                Some(CoordinatorMessage::Connected { node_id, conn })
189→            }
190→            transport::ConnectionEvent::Disconnected { node_id } => {
191→                Some(CoordinatorMessage::Disconnected { node_id })
192→            }
193→        }
194→    }
195→}
196→
197→impl<C: Connection> Default for Coordinator<C> {
198→    fn default() -> Self {
199→        Self::new()
200→    }
201→}
202→
203→impl<C: Connection> Actor for Coordinator<C> {
204→    type Msg = CoordinatorMessage<C>;
205→    type State = CoordinatorState<C>;
206→    type Arguments = (
207→        NodeId,
208→        CourierMode,
209→        Arc<Butler>,
210→        crate::peer_actor::BlobStore,
211→        Option<mpsc::Sender<ConnectRequest>>,
212→        Option<mpsc::Sender<CourierEvent>>,
213→        Option<mpsc::UnboundedSender<MessageTrace>>,
214→        Option<broadcast::Sender<String>>,
215→    );
216→
217→    #[instrument(skip_all)]
218→    async fn pre_start(
219→        &self,
220→        _myself: ActorRef<Self::Msg>,
221→        args: Self::Arguments,
222→    ) -> Result<Self::State, ActorProcessingErr> {
223→        let (our_node_id, mode, butler, blob_store, connect_tx, event_tx, message_tx, capture_tx) = args;
224→
225→        info!("Coordinator started in {:?} mode (node_id={})", mode, our_node_id);
226→
227→        Ok(CoordinatorState::new(
228→            our_node_id,
229→            mode,
230→            butler,
231→            blob_store,
232→            connect_tx,
233→            event_tx,
234→            message_tx,
235→            capture_tx,
236→        ))
237→    }
238→
239→    async fn handle(
240→        &self,
241→        myself: ActorRef<Self::Msg>,
242→        message: Self::Msg,
243→        state: &mut Self::State,
244→    ) -> Result<(), ActorProcessingErr> {
245→        match message {
246→
247→            CoordinatorMessage::Connected { node_id, conn } => {
248→                self.on_connected(myself.clone(), node_id, conn, state).await;
249→            }
250→
251→            CoordinatorMessage::Disconnected { node_id } => {
252→                self.on_disconnected(node_id, state).await;
253→            }
254→
255→            CoordinatorMessage::PeerAuthenticated {
256→                node_id,
257→                peer_type,
258→                did,
259→                username,
260→            } => {
261→                info!("Peer authenticated: {} ({}) - {:?}", username, node_id, peer_type);
262→                state.authenticate_peer(node_id, peer_type, did.clone(), username.clone());
263→
264→                // Mark sovereign node as connected (for User mode connecting to their Node)
265→                if peer_type == PeerType::MyNode {
266→                    let node_id_str = node_id.to_string();
267→                    match state.butler.nodes().set_connected(&node_id_str, true) {
268→                        Ok(true) => info!("Marked sovereign node {} as connected", node_id_str),
269→                        Ok(false) => debug!("Sovereign node {} not found in storage", node_id_str),
270→                        Err(e) => warn!("Failed to mark sovereign node connected: {}", e),
271→                    }
272→                }
273→
274→                // Emit event for app layer
275→                Self::emit_event(state, CourierEvent::PeerAuthenticated {
276→                    node_id: node_id.to_string(),
277→                    did,
278→                    username,
279→                });
280→            }
281→
282→            CoordinatorMessage::PeerFailed { node_id, reason } => {
283→                warn!("Peer failed: {} - {}", node_id, reason);
284→
285→                // Emit failure event for app layer
286→                Self::emit_event(state, CourierEvent::ConnectionFailed {
287→                    node_id: node_id.to_string(),
288→                    error: reason,
289→                });
290→
291→                state.remove_peer(node_id);
292→            }
293→
294→            CoordinatorMessage::Connect { node_id, permit } => {
295→                self.on_connect(node_id, permit, state).await;
296→            }
297→
298→            CoordinatorMessage::GetPeerActor { node_id, response } => {
299→                let actor = state.get_actor(&node_id).cloned();
300→                let _ = response.send(actor);
301→            }
302→
303→            CoordinatorMessage::RelayDatagram { from_node_id, data } => {
304→                if state.mode == CourierMode::Node {
305→                    for (peer_node_id, entry) in state.authenticated_peers() {
306→                        if peer_node_id != from_node_id {
307→                            if let Err(e) = entry.conn.send_datagram(&data) {
308→                                debug!(from = %from_node_id, to = %peer_node_id, error = %e, "Failed to relay datagram");
309→                            }
310→                        }
311→                    }
312→                }
313→            }
314→
315→            CoordinatorMessage::BroadcastDatagram { data } => {
316→                for (node_id, entry) in state.authenticated_peers() {
317→                    if let Err(e) = entry.conn.send_datagram(&data) {
318→                        debug!(node_id = %node_id, error = %e, "Failed to send datagram");
319→                    }
320→                }
321→            }
322→
323→            CoordinatorMessage::EnsureSync { user_did } => {
324→                self.on_ensure_sync(myself.clone(), user_did, state).await;
325→            }
326→
327→            CoordinatorMessage::DistributeLayerPermits { page_id, layer_name, permits } => {
328→                self.on_distribute_layer_permits(&page_id, &layer_name, &permits, state).await;
329→            }
330→
331→            CoordinatorMessage::DistributePagePermitUpdates { page_id, permits } => {
332→                self.on_distribute_page_permit_updates(&page_id, &permits, state).await;
333→            }
334→
335→            CoordinatorMessage::PageOpened { page_id } => {
336→                self.on_page_opened(&page_id, state).await;
337→            }
338→
339→            CoordinatorMessage::IsNodeAuthenticated { node_id, response } => {
340→                let is_auth = state.is_authenticated(&node_id);
341→                let _ = response.send(is_auth);
342→            }
343→
344→            CoordinatorMessage::Shutdown => {
345→                info!("Coordinator shutting down");
346→                for (node_id, entry) in state.peers.drain() {
347→                    debug!("Stopping PeerActor {}", node_id);
348→                    entry.actor.stop(Some("coordinator shutdown".to_string()));
349→                }
350→                myself.stop(Some("shutdown".to_string()));
351→            }
352→        }
353→
354→        Ok(())
355→    }
